(function() {
    'use strict';

    class RedFlagAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'RedFlag Audit: Earnings Quality & Financial Forensics';
            this.version = '1.1.0';

            // Evidence gained per period by decision option
            this.EVIDENCE_P1 = {
                1: { v: 60, cb: 65, h: 50, n: 35 },
                2: { v: 70, cb: 60, h: 45, n: 55 },
                3: { v: 50, cb: 80, h: 30, n: 40 },
                4: { v: 45, cb: 40, h: 55, n: 75 }
            };
            this.EVIDENCE_P2 = {
                1: { v: 30, cb: 5,  h: 5,  n: 5  },
                2: { v: 20, cb: 10, h: 8,  n: 8  },
                3: { v: 15, cb: 15, h: 12, n: 12 },
                4: { v: 20, cb: 10, h: 8,  n: 20 }
            };
            this.EVIDENCE_P3_Q = {
                1: { v: 20, cb: 0,  h: 0,  n: 0  },
                2: { v: 0,  cb: 20, h: 0,  n: 0  },
                3: { v: 0,  cb: 0,  h: 20, n: 0  },
                4: { v: 0,  cb: 0,  h: 0,  n: 25 }
            };
            this.ANALYTICAL_P1 = { 1: 12, 2: 18, 3: 14, 4: 10 };
            this.ANALYTICAL_P2 = { 1: 8,  2: 12, 3: 15, 4: 14 };
            this.CALIB_BONUS   = { 1: -5, 2: 5,  3: 0,  4: 10 };

            this.CORRECT_RECS = { vantara: 'sell', crestbridge: 'sell', harmon: 'hold', novela: 'sell' };
            this.MAX_DET_PTS  = { vantara: 25, crestbridge: 25, harmon: 15, novela: 35 };
            this.NOVELA_TARGET_MULTIPLE = 48.3;

            this.BRIEFINGS = [
                '',
                '<strong>Round 1 — Screening</strong><br>You are a forensic analyst at Meridian Capital Partners. The fund is evaluating four companies for a $120M portfolio allocation. Each has clean audit opinions — but all four may contain earnings quality anomalies.<br><div class="redflag-sim-brief-budget">Budget: 40 analyst hours. Select your screening approach carefully — breadth vs. depth will determine what evidence you can gather.</div><div class="redflag-sim-brief-event">Four companies: Vantara Retail, CrestBridge Technologies, Harmon Consolidated, Novela Pharma. All four have submitted audited financial statements.</div>',
                '<strong>Round 2 — Deep Dive</strong><br>Initial screening is complete. You now have 35 analyst hours for a targeted investigation.<br><div class="redflag-sim-brief-event"><strong>LP Pressure:</strong> One of the fund limited partners has flagged Vantara as a potential short from a peer fund. The portfolio manager is asking for a clear position on Vantara before end of day.</div><div class="redflag-sim-brief-budget">Decision: Do you redirect resources to satisfy LP pressure on Vantara — or maintain your original investigation plan? Consider what you may miss in other companies.</div>',
                '<strong>Round 3 — Synthesis</strong><br>Deep investigation complete. You have 20 analyst hours and 3 management interview questions to synthesize findings.<br><div class="redflag-sim-brief-event"><strong>News Flash:</strong> Novela Pharma announces a secondary equity offering at current market price. No material adverse information disclosed.</div><div class="redflag-sim-brief-budget">Select your most strategic management interview question and decide how to handle the Novela offering in your analysis.</div>',
                '<strong>Round 4 — Investment Committee</strong><br>Present your forensic findings to the investment committee. Submit a Buy / Hold / Sell recommendation for each company and estimate the adjusted EV/EBITDA multiple for Novela Pharma (the company with the largest potential valuation distortion).<br><div class="redflag-sim-brief-budget">Correct adjusted EV/EBITDA for Novela: 48.3x vs. reported 22.8x. Your recommendation accuracy will be weighted by the evidence you gathered in prior rounds.</div>'
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    vantaraEvidence:    0,
                    crestbridgeEvidence: 0,
                    harmonEvidence:     0,
                    novelaEvidence:     0,
                    totalScore:         0,
                    calibrationBonus:   0,
                    detectionBonus:     0,
                    valuationBonus:     0,
                    falsePenalty:       0,
                    findingsLog:        [],
                    scoreHistory:       []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    screeningMethod:        2,
                    deepDiveFocus:          3,
                    mgmtQuestionFocus:      4,
                    offeringResponse:       4,
                    recVantara:             'sell',
                    recCrestBridge:         'sell',
                    recHarmon:              'hold',
                    recNovela:              'sell',
                    adjustedMultipleNovela: 30
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation ? window.mySimulation.state.currentPeriod : 1;
            if (period === 1) {
                var sm = document.getElementById('screeningMethod');
                if (sm) decisions.screeningMethod = parseInt(sm.value);
            } else if (period === 2) {
                var df = document.getElementById('deepDiveFocus');
                if (df) decisions.deepDiveFocus = parseInt(df.value);
            } else if (period === 3) {
                var mq = document.getElementById('mgmtQuestionFocus');
                if (mq) decisions.mgmtQuestionFocus = parseInt(mq.value);
                var or = document.getElementById('offeringResponse');
                if (or) decisions.offeringResponse = parseInt(or.value);
            } else if (period === 4) {
                var rv = document.getElementById('recVantara');
                if (rv) decisions.recVantara = rv.value;
                var rc = document.getElementById('recCrestBridge');
                if (rc) decisions.recCrestBridge = rc.value;
                var rh = document.getElementById('recHarmon');
                if (rh) decisions.recHarmon = rh.value;
                var rn = document.getElementById('recNovela');
                if (rn) decisions.recNovela = rn.value;
                var am = document.getElementById('adjustedMultipleNovela');
                if (am) decisions.adjustedMultipleNovela = parseFloat(am.value) || 0;
            }
            return true;
        }

        calculateResults(state) {
            var d  = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var periodScore = 0;
            var newFindings = [];

            if (period === 1) {
                var g = this.EVIDENCE_P1[d.screeningMethod] || this.EVIDENCE_P1[2];
                ds.vantaraEvidence    = g.v;
                ds.crestbridgeEvidence = g.cb;
                ds.harmonEvidence     = g.h;
                ds.novelaEvidence     = g.n;
                periodScore = this.ANALYTICAL_P1[d.screeningMethod] || 0;
                newFindings = this._findingsP1(d.screeningMethod);

            } else if (period === 2) {
                var g2 = this.EVIDENCE_P2[d.deepDiveFocus] || this.EVIDENCE_P2[3];
                ds.vantaraEvidence    = Math.min(100, ds.vantaraEvidence    + g2.v);
                ds.crestbridgeEvidence = Math.min(100, ds.crestbridgeEvidence + g2.cb);
                ds.harmonEvidence     = Math.min(100, ds.harmonEvidence     + g2.h);
                ds.novelaEvidence     = Math.min(100, ds.novelaEvidence     + g2.n);
                periodScore = this.ANALYTICAL_P2[d.deepDiveFocus] || 0;
                newFindings = this._findingsP2(d.deepDiveFocus, ds);

            } else if (period === 3) {
                var qg = this.EVIDENCE_P3_Q[d.mgmtQuestionFocus] || this.EVIDENCE_P3_Q[4];
                ds.vantaraEvidence    = Math.min(100, ds.vantaraEvidence    + qg.v);
                ds.crestbridgeEvidence = Math.min(100, ds.crestbridgeEvidence + qg.cb);
                ds.harmonEvidence     = Math.min(100, ds.harmonEvidence     + qg.h);
                ds.novelaEvidence     = Math.min(100, ds.novelaEvidence     + qg.n);
                var calib = this.CALIB_BONUS[d.offeringResponse] || 0;
                ds.calibrationBonus = calib;
                periodScore = 5 + calib;
                newFindings = this._findingsP3(d.mgmtQuestionFocus, d.offeringResponse);

            } else if (period === 4) {
                var cos = ['vantara', 'crestbridge', 'harmon', 'novela'];
                var recs = {
                    vantara:    d.recVantara,
                    crestbridge: d.recCrestBridge,
                    harmon:     d.recHarmon,
                    novela:     d.recNovela
                };
                var evArr = {
                    vantara:    ds.vantaraEvidence,
                    crestbridge: ds.crestbridgeEvidence,
                    harmon:     ds.harmonEvidence,
                    novela:     ds.novelaEvidence
                };
                var detPts = 0;
                var fpPts  = 0;
                for (var i = 0; i < cos.length; i++) {
                    var co = cos[i];
                    var ev = evArr[co] / 100;
                    var maxP = this.MAX_DET_PTS[co];
                    if (recs[co] === this.CORRECT_RECS[co]) {
                        detPts += Math.round(maxP * ev);
                    } else if (co === 'harmon' && recs[co] === 'sell') {
                        detPts += Math.round(maxP * ev * 0.4);
                    } else {
                        fpPts += ev > 0.6 ? -12 : -4;
                    }
                }
                var subMult = d.adjustedMultipleNovela || 0;
                var valPts = 0;
                if (subMult > 0) {
                    var pctOff = Math.abs(subMult - this.NOVELA_TARGET_MULTIPLE) / this.NOVELA_TARGET_MULTIPLE;
                    if (pctOff <= 0.15)      valPts = 20;
                    else if (pctOff <= 0.30) valPts = 12;
                    else if (pctOff <= 0.50) valPts = 5;
                }
                ds.detectionBonus = detPts;
                ds.falsePenalty   = fpPts;
                ds.valuationBonus = valPts;
                // Calibration bonus is already credited in Round 3 (periodScore = 5 + calib),
                // matching the "+N pts" message shown to the student that round. Re-adding it here
                // double-counted it in the final total. (fix v1.1.0)
                periodScore = detPts + fpPts + valPts;
                newFindings = this._findingsP4(recs, evArr, detPts, fpPts, valPts);
            }

            ds.totalScore = (ds.totalScore || 0) + periodScore;
            ds.scoreHistory.push(Math.max(0, ds.totalScore));
            if (!ds.findingsLog) ds.findingsLog = [];
            ds.findingsLog = ds.findingsLog.concat(newFindings);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation ? window.mySimulation.state : { currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period:              period,
                periodScore:         periodScore,
                totalScore:          ds.totalScore,
                vantaraEvidence:     ds.vantaraEvidence,
                crestbridgeEvidence: ds.crestbridgeEvidence,
                harmonEvidence:      ds.harmonEvidence,
                novelaEvidence:      ds.novelaEvidence
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay',      'currentPeriod');
            uiManager.bind('maxPeriods',      'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore',
                function(v) { return Math.max(0, v || 0); });
            uiManager.bind('detectionDisplay', 'domainState.detectionBonus',
                function(v) { return v !== undefined && v !== null && v !== 0 ? '+' + v : '—'; });
            uiManager.bind('valuationDisplay', 'domainState.valuationBonus',
                function(v) { return v !== undefined && v !== null && v !== 0 ? '+' + v : '—'; });
            uiManager.bind('penaltyDisplay', 'domainState.falsePenalty',
                function(v) { return v !== undefined && v !== null && v !== 0 ? v : '—'; });
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Cumulative Score',
                            data: [],
                            backgroundColor: 'rgba(44,62,107,0.75)',
                            borderColor: '#1a2744',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cumulative Score by Round', color: '#1a2744', font: { size: 13, weight: 'bold' } },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, grid: { color: 'rgba(0,0,0,0.06)' } },
                            x: { grid: { display: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var hist = state.domainState.scoreHistory || [];
            var labels = ['Round 1', 'Round 2', 'Round 3', 'Round 4'].slice(0, hist.length);
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: hist }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            // Clamp to 0 for display consistency with the on-screen score (the raw running total can
            // dip slightly negative on poor play; classification thresholds are unaffected). (v1.1.0)
            var total = Math.max(0, last.results ? (last.results.totalScore || 0) : 0);
            var performance, insights;
            if (total >= 120) {
                performance = 'Elite Analyst';
                insights = ['Exceptional forensic accuracy — your evidence coverage and valuation adjustments are at institutional quality.', 'You demonstrated calibrated skepticism: distinguishing confirmed manipulation from aggressive-but-legal accounting.'];
            } else if (total >= 90) {
                performance = 'Competent Analyst';
                insights = ['Strong detection accuracy with some evidence coverage gaps.', 'Review multi-document cross-referencing technique for related-party schemes like round-tripping.'];
            } else if (total >= 60) {
                performance = 'Developing Analyst';
                insights = ['You identified several key anomalies but may have over- or under-allocated your investigation hours.', 'Revisit the Beneish M-Score component analysis and the accrual ratio cross-check.'];
            } else {
                performance = 'Beginner';
                insights = ['Focus on the M-Score components — specifically DSRI (receivables growth) and TATA (accruals) as primary screens.', 'In round 2, maintaining a balanced investigation plan typically outperforms following single-company pressure.'];
            }
            return { totalScore: total, performance: performance, insights: insights };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            var ds = state.domainState;
            if (period === 1 && ds.novelaEvidence < 45) {
                return window.mySimulation.t('hint_novela_proxy');
            }
            if (period === 2 && ds.novelaEvidence < 60) {
                return window.mySimulation.t('hint_balance');
            }
            if (period === 3 && ds.harmonEvidence < 50) {
                return window.mySimulation.t('hint_harmon');
            }
            if (period === 4 && (ds.vantaraEvidence + ds.novelaEvidence) < 100) {
                return window.mySimulation.t('hint_evidence_gaps');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',              label: 'Round',        i18nKey: 'col_round' },
                { key: 'results.vantaraEvidence',     label: 'Vantara %',    i18nKey: 'col_vantara',    formatter: function(v) { return Math.round(v || 0) + '%'; } },
                { key: 'results.crestbridgeEvidence', label: 'CrestBridge %', i18nKey: 'col_crest',     formatter: function(v) { return Math.round(v || 0) + '%'; } },
                { key: 'results.harmonEvidence',      label: 'Harmon %',     i18nKey: 'col_harmon',     formatter: function(v) { return Math.round(v || 0) + '%'; } },
                { key: 'results.novelaEvidence',      label: 'Novela %',     i18nKey: 'col_novela',     formatter: function(v) { return Math.round(v || 0) + '%'; } },
