            var out = ['<span class="rf-dim">— Round 4 Investment Committee Recommendations —</span>'];
            var correct = this.CORRECT_RECS;
            var names = { vantara: 'Vantara', crestbridge: 'CrestBridge', harmon: 'Harmon', novela: 'Novela' };
            var keys = ['vantara', 'crestbridge', 'harmon', 'novela'];
            for (var i = 0; i < keys.length; i++) {
                var co = keys[i];
                var ev = Math.round(evArr[co] || 0);
                var rec = (recs[co] || '').toUpperCase();
                var isCorrect = recs[co] === correct[co];
                var isPartial = co === 'harmon' && recs[co] === 'sell';
                if (isCorrect) {
                    out.push('<span class="rf-green">✔ ' + names[co] + '</span>: ' + rec + ' — correct. Evidence: ' + ev + '%. Points awarded based on evidence coverage.');
                } else if (isPartial) {
                    out.push('<span class="rf-amber">~ ' + names[co] + '</span>: ' + rec + ' — direction correct but overcalled (correct answer: HOLD for ambiguous cookie-jar pattern). Partial credit.');
                } else {
                    out.push('<span class="rf-red">✘ ' + names[co] + '</span>: ' + rec + ' — incorrect (correct: ' + correct[co].toUpperCase() + '). Evidence level: ' + ev + '%. ' + (ev > 60 ? 'False positive/negative penalty applied.' : 'Limited evidence — penalty reduced.'));
                }
            }
            out.push('<span class="rf-blue">Detection points: ' + detPts + '</span> | <span class="rf-red">FP penalty: ' + fpPts + '</span> | <span class="rf-green">Valuation score: +' + valPts + '</span>');
            if (valPts === 20) {
                out.push('<span class="rf-green">✔ Novela EV/EBITDA estimate within 15% of correct answer (48.3×). Full valuation score awarded.</span>');
