                out.push('<span class="rf-amber">~ Novela EV/EBITDA estimate within 50% of correct answer (48.3×). Minimal valuation score.</span>');
            } else {
                out.push('<span class="rf-red">✘ Novela EV/EBITDA estimate too far from correct answer (48.3×). No valuation score.</span>');
